import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'
import type { MoonlightcodePhaseRequest, MoonlightcodePlan, MoonlightcodeReviewView } from '../types'
import {
  anchorLabel,
  anchorOf,
  anchorOfRows,
  continueDraft,
  excerptOf,
  excerptOfRows,
  nextRowSelection,
  type RowRange,
  formatReview,
  inRepo,
  isInAnchor,
  isSplit,
  lineHunk,
  parseChangedFiles,
